async function filesystemRuntime(storage) {
    if (storage.kind !== "filesystem" || !storage.runtimeModuleUrl)
        throw new Error("FilesystemStorage must provide its native runtime module; update @lix-js/storage-filesystem to match the SDK");
    return import(/* @vite-ignore */ storage.runtimeModuleUrl);
}
export async function openLixBinding(storage, telemetry, parent, server, progress, snapshot) {
    if (storage.kind === "filesystem")
        return (await filesystemRuntime(storage)).openLixBinding(storage, telemetry, parent, server, progress, snapshot);
    return (await import("./binding.node-wasm.js")).openNodeWasmBinding(storage, telemetry, parent, server, progress, snapshot);
}
export async function createHostedBinding(...args) {
    return (await import("./binding.browser.js")).createHostedBinding(...args);
}
export async function deleteHostedBinding(...args) {
    return (await import("./binding.browser.js")).deleteHostedBinding(...args);
}
export async function convertReplicaBinding(storage, ...args) {
    const runtime = storage.kind === "filesystem"
        ? await filesystemRuntime(storage)
        : await import("./binding.browser.js");
    return runtime.convertReplicaBinding(storage, ...args);
}
export async function retryReplicaMigrationCleanupBinding(storage, ...args) {
    const runtime = storage.kind === "filesystem"
        ? await filesystemRuntime(storage)
        : await import("./binding.browser.js");
    return runtime.retryReplicaMigrationCleanupBinding(storage, ...args);
}
